12	// newObservedLogger 以 observer core 包 WrapCore，回傳 logger 與可觀測 logs。
13	func newObservedLogger(rules InterceptRules) (*zap.Logger, *observer.ObservedLogs) {
14		obsCore, logs := observer.New(zapcore.InfoLevel)
15		return zap.New(WrapCore(obsCore, rules)), logs
16	}
17	
18	// fieldByKey 從 entry 取出指定 key 的 field。
19	func fieldByKey(t *testing.T, entry observer.LoggedEntry, key string) zapcore.Field {
20		t.Helper()
21		for _, f := range entry.Context {
22			if f.Key == key {
23				return f
24			}
25		}
26		t.Fatalf("找不到 key %q 的 field", key)
27		return zapcore.Field{}
28	}
29	
30	func TestWrapCore_KeywordMatchMasksString(t *testing.T) {
31		logger, logs := newObservedLogger(InterceptRules{Keywords: []string{"phone"}})
32		logger.Info("login", zap.String("phone", "0987654321"))
33	
34		entry := logs.All()[0]
35		if got := fieldByKey(t, entry, "phone").String; got != "**********" {
36			t.Errorf("phone 應被全遮罩，got %q", got)
37		}
38	}
39	
40	func TestWrapCore_PatternMatchMasksString(t *testing.T) {
41		rules := InterceptRules{Patterns: []*regexp.Regexp{regexp.MustCompile(`(?i)secret`)}}
42		logger, logs := newObservedLogger(rules)
43		logger.Info("auth", zap.String("api_secret", "abcdef"))
44	
